// Increase ROAS tailnet policy: least privilege. Built 2026-10-02 from the traffic each machine really uses
// (job work/2026-10-02_network-rules, flows table in notes/network-rules.md). Anything not allowed here is blocked.
{
	// Fixed tailnet addresses, so a rule or test can name one machine without changing any tags.
	// The rules (grants) use only javante and javar-orgo. Their addresses, and those of Alex's MacBook and iPhone, stay
	// unless the machine is removed and added again.
	// The six marked "ephemeral" are Orgo machines that come back with a new address when rebuilt. Only "deny" tests name
	// them, so a stale line blocks nothing; update it when that happens.
	"hosts": {
		"javante":           "100.127.38.125",  // Mac mini (agent@): Javante's Hermes and the home exit node
		"javar-orgo":        "100.84.107.10",   // Orgo "EA": Javar's Hermes
		"alexs-macbook-pro": "100.90.100.19",   // Alex
		"iphone172":         "100.82.76.7",     // Alex
		"alexs-macbook-pro-v6": "fd7a:115c:a1e0::ee39:6414", // Alex (IPv6, used only in the tag:server test)
		"iphone172-v6":         "fd7a:115c:a1e0::9b39:4c08", // Alex (IPv6, used only in the tag:server test)
		"openclaw-hub":      "100.122.97.7",    // Orgo "My OpenClaw": the MCP hub (shields up); ephemeral
		"b2b-sales-agent":   "100.99.199.66",   // ephemeral
		"csm-agent":         "100.81.140.39",   // ephemeral
		"max-finance":       "100.82.217.115",  // ephemeral
		"media-agent":       "100.118.227.107", // ephemeral
		"ops-coordinator":   "100.78.72.70",    // ephemeral
	},

	"grants": [
		// 1. Alex's devices (MacBook, iPhone) reach every machine on every port, and the internet through an exit node.
		{"src": ["alex@increaseroas.com"], "dst": ["*"], "ip": ["*"]},

		// 2. Every Orgo machine browses through the home exit node (javante). That needs internet access only,
		//    not access to the Mac mini itself (DNS through the exit node is checked against this same rule).
		{"src": ["tag:server"], "dst": ["autogroup:internet"], "ip": ["*"]},

		// 3. Javar -> Javante, A2A: Javar's a2a-javante-proxy calls 100.127.38.125:9900 (Serve TCP forward on javante).
		{"src": ["javar-orgo"], "dst": ["javante"], "ip": ["tcp:9900"]},

		// 4. Javante -> Javar: the GHL Command MCP bridge (18881), and Javar's documented fallback file push (9999).
		//    9999 is your call: delete "tcp:9999" (and the test that names it) if files should only go through Drive.
		{"src": ["javante"], "dst": ["javar-orgo"], "ip": ["tcp:18881", "tcp:9999"]},
	],

	"ssh": [
		// Alex (no agent) may SSH into the Orgo machines, as root or any other user.
		{
			"action": "accept",
			"src":    ["alex@increaseroas.com"],
			"dst":    ["tag:server"],
			"users":  ["root", "autogroup:nonroot"],
		},
		// Tailscale's default: each person may SSH into their own devices after a fresh sign-in.
		{
			"action": "check",
			"src":    ["autogroup:member"],
			"dst":    ["autogroup:self"],
			"users":  ["autogroup:nonroot", "root"],
		},
	],

	// Who may put the tag:server label on a machine: admins as before, plus Alex by name, so he keeps it after agent@
	// becomes a Member (Tailscale's docs don't promise that the Owner counts as an admin).
	"tagOwners": {"tag:server": ["autogroup:admin", "alex@increaseroas.com"]},

	// Funnel (public internet exposure) is no longer granted: no machine uses it (checked 2026-10-02 on the MacBook,
	// javante, javar-orgo and the other six Orgo machines; the iPhone was offline).

	// Checks Tailscale runs on every save. If one fails, the console refuses to save.
	// 1.1.1.1:443 and 8.8.8.8:53 stand for "the internet through the exit node" (exit-node DNS is checked on port 53).
	// Tests name both identities (people, tags) and the machines' real addresses, so a leak to a tested port is caught
	// whether a future rule names a person, a tag or an address. Ports not listed here aren't tested.
	"tests": [
		// Alex reaches what he uses: the Hermes app on Javar and Javante, the Mac mini's SSH, SSH into every Orgo
		// machine, and the internet.
		{
			"src":    "alex@increaseroas.com",
			"accept": ["javar-orgo:443", "javar-orgo:9119", "javante:443", "javante:22", "javante:9900", "tag:server:22", "1.1.1.1:443"],
		},
		// Javar: A2A to Javante, and the internet through the exit node. Nothing else.
		{
			"src":    "javar-orgo",
			"accept": ["javante:9900", "1.1.1.1:443", "8.8.8.8:53"],
			"deny":   ["javante:22", "javante:443", "javante:5900", "alexs-macbook-pro:22", "iphone172:443", "alex@increaseroas.com:22", "alex@increaseroas.com:443", "openclaw-hub:8100", "b2b-sales-agent:22"],
		},
		// Javante: the GHL bridge and the file push on Javar. Nothing else.
		{
			"src":    "javante",
			"proto":  "tcp",
			"accept": ["javar-orgo:18881", "javar-orgo:9999"],
			"deny":   ["javar-orgo:22", "javar-orgo:9119", "javar-orgo:8644", "alexs-macbook-pro:22", "iphone172:443", "alex@increaseroas.com:22", "alex@increaseroas.com:443", "b2b-sales-agent:22", "tag:server:22", "tag:server:8080"],
		},
		// Any Orgo machine by its tag: the internet through the exit node, nothing on the tailnet.
		{
			"src":    "tag:server",
			"accept": ["1.1.1.1:443", "8.8.8.8:53"],
			"deny":   ["alexs-macbook-pro:22", "alexs-macbook-pro:443", "iphone172:443", "alexs-macbook-pro-v6:22", "iphone172-v6:443", "alex@increaseroas.com:22", "alex@increaseroas.com:443", "javante:22", "javante:5900", "javante:9900", "javar-orgo:18881", "javar-orgo:9119", "javar-orgo:22", "tag:server:8080", "tag:server:6080", "tag:server:9223"],
		},
		// The hub and the five agents by address (deny only, so a stale ephemeral address can't block a save).
		{"src": "openclaw-hub",    "deny": ["alexs-macbook-pro:22", "iphone172:443", "javante:22", "javante:9900", "javar-orgo:18881", "javar-orgo:22"]},
		{"src": "b2b-sales-agent", "deny": ["alexs-macbook-pro:22", "iphone172:443", "javante:22", "javante:9900", "javar-orgo:18881", "csm-agent:8080"]},
		{"src": "csm-agent",       "deny": ["alexs-macbook-pro:22", "iphone172:443", "javante:22", "javante:9900", "javar-orgo:18881", "max-finance:6080"]},
		{"src": "max-finance",     "deny": ["alexs-macbook-pro:22", "iphone172:443", "javante:22", "javante:9900", "javar-orgo:18881", "media-agent:8080"]},
		{"src": "media-agent",     "deny": ["alexs-macbook-pro:22", "iphone172:443", "javante:22", "javante:9900", "javar-orgo:18881", "ops-coordinator:8080"]},
		{"src": "ops-coordinator", "deny": ["alexs-macbook-pro:22", "iphone172:443", "javante:22", "javante:9900", "javar-orgo:18881", "openclaw-hub:8100"]},
	],

	"sshTests": [
		// Alex can SSH into the Orgo machines as root.
		{"src": "alex@increaseroas.com", "dst": ["tag:server"], "accept": ["root"]},
		// Agents can't SSH into each other, and agent@ (javante) can't SSH into them, as root or as another user.
		{"src": "tag:server", "dst": ["tag:server"], "deny": ["root", "javar"]},
		{"src": "<agent login>", "dst": ["tag:server"], "deny": ["root", "javar"]},
	],
}
